import * as zod from "zod";
import { ApprovalMode } from "./approvalMode.zod.js";
import { ContextUsageResource } from "./contextUsageResource.zod.js";
import { LastTurnResource } from "./lastTurnResource.zod.js";
import { PendingActionResource } from "./pendingActionResource.zod.js";
import { ReasoningEffort } from "./reasoningEffort.zod.js";
import { SubagentCountResource } from "./subagentCountResource.zod.js";
import { ThreadStatus } from "./threadStatus.zod.js";
import { TodoResource } from "./todoResource.zod.js";
import { Usage } from "./usage.zod.js";

export const threadResourceOrderVersionMin = 0;

export const ThreadResource = zod
  .strictObject({
    id: zod.string(),
    role: zod
      .enum(["main", "subagent"])
      .describe(
        "`main` for a conversation with a person, `subagent` for one started by another agent.",
      ),
    parentId: zod
      .string()
      .nullable()
      .describe("The conversation that started this subagent. Null for main conversations."),
    agentName: zod
      .string()
      .nullable()
      .describe(
        "The subagent's name, unique among the subagents of its parent. Null for main conversations.",
      ),
    title: zod.string().nullable().describe("Null until the conversation has a name."),
    folderId: zod
      .string()
      .nullable()
      .describe(
        "The folder that holds this conversation. Null for subagents, which are not filed.",
      ),
    orderVersion: zod
      .int()
      .min(threadResourceOrderVersionMin)
      .describe(
        "The version of this conversation's place in its folder. Pass it as `expectedVersion` when moving it.",
      ),
    modelId: zod.string().describe("The Canopy model the next model request uses."),
    reasoningEffort: zod
      .union([ReasoningEffort, zod.null()])
      .describe("Null when the model does not reason."),
    approvalMode: ApprovalMode,
    status: ThreadStatus,
    activity: zod
      .string()
      .nullable()
      .describe(
        'What the assistant is doing right now, for example "Reading nginx.conf". Null when idle.',
      ),
    recentMessage: zod
      .string()
      .nullable()
      .describe("The beginning of the assistant's latest message."),
    todos: zod
      .array(TodoResource)
      .describe("The assistant's current plan, in order. Empty when it has none."),
    pendingAction: zod
      .union([PendingActionResource, zod.null()])
      .describe(
        "What this conversation is waiting for from a person. It may belong to one of its subagents.",
      ),
    subagents: SubagentCountResource,
    lastTurn: zod
      .union([LastTurnResource, zod.null()])
      .describe("The most recent turn. Null before the first message."),
    context: ContextUsageResource,
    usage: Usage.describe(
      "Token usage over the whole conversation. For a main conversation this includes its subagents.",
    ),
    unread: zod
      .boolean()
      .describe("The assistant replied after the conversation was last marked read."),
    archived: zod.boolean(),
    createdAt: zod.iso.datetime({ offset: true }),
    updatedAt: zod.iso
      .datetime({ offset: true })
      .describe("The last activity. Renaming or moving the conversation does not change it."),
  })
  .describe(
    "A conversation with an agent. The main conversation and its subagents have the same shape;\n`role` tells them apart.",
  );

export type ThreadResource = zod.input<typeof ThreadResource>;
export type ThreadResourceOutput = zod.output<typeof ThreadResource>;
